definitions.definition:
pub struct View {
    // the existing fields stay
    /// Fold ranges that are shut. Each one is also in `folds`.
    pub collapsed: Vec<CharRange>,
}

impl View {
    /// Shut the innermost fold range at `at`, or open it when it is shut. False when no range contains `at`.
    pub fn toggle_fold_at(&mut self, at: Offset) -> bool;
    /// Drop every collapsed range that is not in `folds`.
    pub fn retain_live_collapsed(&mut self);
}

pub enum Command {
    // the existing variants stay
    /// Fold or unfold the region at the primary caret.
    ToggleFold,
}
